"""Derive SkyyTrees/build_skyytrees_0.6.8.py from SkyyTrees 0.6.7 (build_skyytrees_0.6.7.py = the SET pin, itself GENERATED by
tools/trees_0_6_7_patch.py). Edit THIS patch, never the generated script. Every anchor is asserted once; at the end every change is undone on
a copy and compared with 0.6.7 (tools/soundpass_gen.Patch).
Run:
    python tools/trees_0_6_8_patch.py && python SkyyTrees/build_skyytrees_0.6.8.py && python SkyyTrees/test_skyytrees_0.6.8.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.6.8 (2026-11-21) = THE SICKLE RIGHT SWING NO LONGER LOGS A SEVERE (small fixes round fix1; Skyy 2026-11-21 "build and deploy everything on
  your list"; docs/log/2026-11.md 2026-11-08 LOGS + DIAGNOSIS). No Java change but the version.
  The live log of 2026-11-08 had "Missing replacement interactions for interaction: Skyy_Tree_HarvR_HE for var Sickle_Swing_Right_Damage on
  item Tool_Sickle_Harvester_Bronze_SkyWynn" (SEVERE). Cause: vanilla Sickle_Swing_Right_Selector's HitEntity Replace (unlike the Left one)
  has no "DefaultOk": true and names the var "Sickle_Swing_Right_Damage", which no sickle defines (they define Swing_Right_Damage). The
  engine (ReplaceInteraction.doReplace, bytecode 2026-11-21) then LOGS the SEVERE and runs the DefaultValue anyway; with DefaultOk true it
  runs the same DefaultValue silently. 0.5.2's copy of that selector (our override at the vanilla path, flattened into Skyy_Tree_HarvR_HE)
  kept it as it was.
  1. The copy's HitEntity Replace (Right only; Left already has it) gets "DefaultOk": true - nothing else in it changes (DefaultValue
     Sickle_Swing_Right_Damage, Var kept). A right-swing hit on a mob does exactly what it did (the default damage chain), without the SEVERE.
     Build-time self-check: the vanilla Replace still has Type / DefaultValue / Var; the patch adds DefaultOk only where vanilla lacks it.
  Not changed: the 55 Sickle_Attack chain WARNs of the same log (separate, unproven - swing pad or click spam); the Var name (renaming it to
  Swing_Right_Damage would switch on each sickle's own right-hit sound = a behaviour change, left for a design call).
  SAVED DATA: none. ROLLBACK to 0.6.7: alone (the SEVERE line comes back on a right-swing mob hit; nothing else).
'''

P = G.Patch(os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.7.py"), os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.8.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.6.7"') and P.has("0.6.7 (2026-10-30) = WEAPONCRAFT x1.5 TEXT") and not P.has("0.6.8 (2026-11-21)"), "not the generated SkyyTrees 0.6.7 script"
REG0, SYS0, CLS0, M0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("makeClass("), P.s.count("\nM(")

P.rep('''"""SkyyTrees 0.6.7 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_7_patch.py from build_skyytrees_0.6.6.py (the SET pin) - edit the patch, not this file.
''', '''"""SkyyTrees 0.6.8 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_8_patch.py from build_skyytrees_0.6.7.py (the SET pin) - edit the patch, not this file.
''' + NOTE + '''
SkyyTrees 0.6.7 - GENERATED by tools/trees_0_6_7_patch.py from build_skyytrees_0.6.6.py:
''')
P.rep('VERSION = "0.6.7"', 'VERSION = "0.6.8"')

# the DefaultOk on the copy's HitEntity Replace (after 0.5.2's "differs only in Next" self-check, before the flatten names the step)
P.rep('''HARV_FLAT = {}
with zipfile.ZipFile(ASSETS) as _hz:
''', '''HARV_FLAT = {}
HARV_DEFOK = []   # 0.6.8: the sides whose HitEntity Replace got "DefaultOk": true (vanilla lacks it on the Right selector)
with zipfile.ZipFile(ASSETS) as _hz:
''')
P.rep('''            raise SystemExit("harvest swing self-check: the copy differs from vanilla %s in more than Next" % _sel)
''', '''            raise SystemExit("harvest swing self-check: the copy differs from vanilla %s in more than Next" % _sel)
        # 0.6.8: a missing var on a Replace without DefaultOk logs a SEVERE (ReplaceInteraction.doReplace) and still runs DefaultValue;
        # DefaultOk true runs the same DefaultValue silently. Only the flag is added; Type / DefaultValue / Var stay vanilla.
        _he = _ov["HitEntity"]["Interactions"][0]
        if not isinstance(_he, dict) or _he.get("Type") != "Replace" or "DefaultValue" not in _he or "Var" not in _he or len(_ov["HitEntity"]["Interactions"]) != 1:
            raise SystemExit("harvest swing self-check (0.6.8): %s's HitEntity is no longer one Replace with DefaultValue + Var: %s" % (_sel, json.dumps(_ov["HitEntity"])[:300]))
        if _he.get("DefaultOk") is not True:
            _ov["HitEntity"]["Interactions"][0] = dict([("Type", "Replace"), ("DefaultOk", True)] + [(k_, v_) for k_, v_ in _he.items() if k_ not in ("Type", "DefaultOk")])
            HARV_DEFOK.append(_sd)
''')
P.rep('''SWING_FILES.update(HARV_FILES)
''', '''SWING_FILES.update(HARV_FILES)
# 0.6.8: vanilla 2026-11 lacks DefaultOk on the Right selector only; every Replace step of the harvest copies now has it
assert HARV_DEFOK in ([], ["Right"]), ("0.6.8: unexpected DefaultOk fixes", HARV_DEFOK)
_HV_REPL = [(_n, _b) for _n, _b in HARV_FLAT.items() if _b.get("Type") == "Replace"]
assert sorted(_n for _n, _b in _HV_REPL) == ["Skyy_Tree_HarvL_HE", "Skyy_Tree_HarvR_HE"] and all(_b.get("DefaultOk") is True for _n, _b in _HV_REPL), _HV_REPL
print("0.6.8 sickle Replace: DefaultOk added on %s (Skyy_Tree_HarvL_HE / Skyy_Tree_HarvR_HE both DefaultOk now)" % (HARV_DEFOK or "nothing - vanilla has it"))
''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("makeClass(") == CLS0 and P.s.count("\nM(") == M0, "0.6.8: no new class / system / command / method"
P.finish()
print("wrote", P.dst)
